/* 
  The Holy Grail of REST: The CRUD to HTTP Mapping
*/

// [C]REATE -> POST
fetch('/api/tasks', { 
  method: 'POST', 
  body: JSON.stringify({ title: 'Buy milk' }) 
});

// [R]EAD -> GET
fetch('/api/tasks', { 
  method: 'GET' 
});

// [U]PDATE -> PUT (or PATCH)
fetch('/api/tasks/99', { 
  method: 'PUT', 
  body: JSON.stringify({ title: 'Buy almond milk', completed: true }) 
});

// [D]ELETE -> DELETE
fetch('/api/tasks/99', { 
  method: 'DELETE' 
});
